<section class="page-header"><div><div class="page-eyebrow">SEGURIDAD Y ACCESO</div><h1 class="page-title">Usuarios, roles y sesiones</h1><p class="page-subtitle">Control administrativo de identidades y trazabilidad de accesos.</p></div></section>
<div class="row g-4">
<div class="col-xl-7"><div class="card h-100"><div class="card-header bg-white"><strong>Usuarios</strong></div><div class="table-responsive"><table class="table app-table mb-0"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=e($u['nombre'])?></td><td><?=e($u['email'])?></td><td><?=e($u['roles']??'—')?></td><td><?=e($u['estado'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div class="col-xl-5"><div class="card h-100"><div class="card-header bg-white"><strong>Roles</strong></div><div class="table-responsive"><table class="table app-table mb-0"><thead><tr><th>Rol</th><th>Usuarios</th><th>Permisos</th></tr></thead><tbody><?php foreach($roles as $r): ?><tr><td><strong><?=e($r['nombre'])?></strong><small class="d-block text-muted"><?=e($r['descripcion']??'')?></small></td><td><?=e($r['usuarios'])?></td><td><?=e($r['permisos'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>
</div>
<div class="card mt-4"><div class="card-header bg-white"><strong>Actividad de acceso</strong></div><div class="table-responsive"><table class="table app-table mb-0"><thead><tr><th>Fecha</th><th>Usuario</th><th>IP</th><th>Acción</th></tr></thead><tbody><?php foreach($sessions as $s): ?><tr><td><?=e($s['fecha_hora'])?></td><td><?=e($s['usuario']??'Cuenta no identificada')?></td><td><?=e($s['ip']??'—')?></td><td><?=e($s['accion'])?></td></tr><?php endforeach;?></tbody></table></div></div>